const tasks = yield* Database.query(Filter.type(types['com.example.type.task'], { status: 'open' })).run;
const results = [];
for (const t of tasks) {
  const r = yield* Operation.invoke(ops['dxn:com.example.operation.score'], { title: t.title });
  yield* print('scored', JSON.stringify({ title: t.title, raw: r }));
  results.push({ t, r });
}

const tasks = yield* Database.query(Filter.type(types['com.example.type.task'], { status: 'open' })).run;
for (const t of tasks) {
  const score = yield* Operation.invoke(ops['dxn:com.example.operation.score'], { title: t.title });
  Obj.update(t, (task) => { task.priority = score; });
}
yield* Database.flush();
const after = yield* Database.query(Filter.type(types['com.example.type.task'], { status: 'open' })).run;
for (const t of after) {
  yield* print('stored', JSON.stringify({ title: t.title, priority: t.priority }));
}
